"""Конфигурация клиента: clients/<slug>.toml."""
from __future__ import annotations

import tomllib
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CLIENTS_DIR = ROOT / "clients"


@dataclass
class ClientConfig:
    slug: str
    name: str
    partner_channels: list[str]
    clubs: dict[int, dict] = field(default_factory=dict)

    def club(self, club_id: int) -> dict:
        """Настройки конкретного клуба (пустой словарь, если их нет)."""
        return self.clubs.get(club_id, {})


def load_config(slug: str, clients_dir: Path = CLIENTS_DIR) -> ClientConfig:
    with open(clients_dir / f"{slug}.toml", "rb") as f:
        raw = tomllib.load(f)
    clubs = {int(club_id): settings for club_id, settings in raw.get("clubs", {}).items()}
    return ClientConfig(
        slug=slug,
        name=raw["name"],
        partner_channels=raw["import"]["partner_channels"],
        clubs=clubs,
    )

"""Схема базы отчётов (SQLite)."""
import sqlite3
from pathlib import Path

SCHEMA = """
CREATE TABLE clubs (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    opened_at TEXT NOT NULL
);
CREATE TABLE trainers (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    name TEXT NOT NULL
);
CREATE TABLE persons (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE visits (
    id INTEGER PRIMARY KEY,
    person_id INTEGER NOT NULL,
    club_id INTEGER NOT NULL,
    visit_date TEXT NOT NULL,
    visit_type TEXT NOT NULL            -- regular | trial | guest_pass
);
CREATE TABLE sales (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    person_id INTEGER,                  -- у продаж бара покупатель неизвестен
    sale_date TEXT NOT NULL,
    kind TEXT NOT NULL,                 -- membership | personal_training | bar
    amount_kop INTEGER NOT NULL,
    channel TEXT NOT NULL CHECK (channel IN ('own', 'partner'))
);
CREATE TABLE sessions (
    id INTEGER PRIMARY KEY,
    club_id INTEGER NOT NULL,
    trainer_id INTEGER NOT NULL,
    person_id INTEGER NOT NULL,
    session_date TEXT NOT NULL,
    sale_id INTEGER NOT NULL
);
"""


def connect(path: str | Path = ":memory:") -> sqlite3.Connection:
    return sqlite3.connect(path)


def create_schema(conn: sqlite3.Connection) -> None:
    conn.executescript(SCHEMA)
